bounded_host_request.command:
set -euo pipefail
cid=gace-createvdobot-videobot-poll-1
test "$(docker inspect "$cid" --format '{{.State.Running}}' 2>/dev/null)" = true
docker exec -i -w /opt/videobot "$cid" node --input-type=module <<'JS'
import {readPrivateToken} from '/opt/videobot/src/runtime/config.mjs';
import {createCreatorTelegramFetch} from '/opt/videobot/src/runtime/creatorEgress.mjs';
const env=process.env;
const outbound=createCreatorTelegramFetch();
const botToken=readPrivateToken(env.VIDEOBOT_TELEGRAM_TOKEN_FILE);
const base=env.VIDEOBOT_LOCAL_API_URL??'https://api.telegram.org';
async function get(method,args) {
 const response=await outbound.fetch(base+'/bot'+botToken+'/'+method,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(args)});
 let data=await response.json().catch(()=>({}));
 const message=String(data.description??'').replace(/[-]?[0-9]{8,}/g,'[ID]').replace(/(https?:\/\/)[^ ]+/g,'[URL]');
 console.log(method+' HTTP='+response.status+' STATUS='+String(data.ok)+' ERROR='+message.slice(0,140));
 if(data.ok)return data.result;
 return null;
}
try{
 const chat=await get('getChat',{chat_id:-1002373696859});
 const admins=await get('getChatAdministrators',{chat_id:-1002373696859});
 if(Array.isArray(admins)) {
   const match=admins.find(v=>v.user?.id===788044853);
   console.log('MASTER_KNOWN_ACCOUNT_ROLE='+(match?.status??'not_listed_as_admin'));
   console.log('MASTER_KNOWN_ACCOUNT_CREATOR='+(match?.status==='creator'));
 }
 console.log('BOARD_TYPE='+String(chat?.type??'unknown'));
}finally{await outbound.close()}
JS
